// Imports
use std::io;

fn main() {
    // Prompt user for input
    println!("Enter a number:");
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");

    // Parse input
    let number: i32 = match input.trim().parse() {
        Ok(num) => num,
        Err(_) => {
            println!("Invalid input. Please enter a valid number.");
            return;
        }
    };

    // Print the number
    println!("You entered: {}", number);
}
```

**Key points:**
- **Imports:** Only import what you need.
- **Explicit typing:** Use type inference where possible, but be explicit when it improves readability.
- **Error handling:** Use `?` for simple errors, or `match` for more complex cases.
- **Readability:** Use descriptive variable names and comments where needed.
- **Avoid unnecessary complexity:** Don't overcomplicate simple logic.

